-- Platsbeskrivningar, omgång 2 (36 platser). Skrivna utifrån platsernas egna hemsidor.
-- Kort text högst 7 ord, lång 70–100 ord.
begin;
update public.places set short_description = 'Konstnären Gunilla Manns ateljé och galleri', description = 'Gunilla Mann Gallery är konstnären Gunilla Manns ateljé och galleri i Rörum. Gunilla är född och uppvuxen i Göteborg och utbildad vid Göteborgs konstslöjdförening och Börje Hovedskous målarskola, som senare blev Göteborgs konstskola. I dag bor hon både på Österlen och på Södermalm i Stockholm. Hennes målningar finns som original, litografier och tryck, och motiven finns även på brickor och pussel. Man kan beställa en egen målning av en plats, en byggnad eller en händelse. Verken säljs också i en webbshop.' where id = 65; -- Gunilla Mann Gallery
update public.places set short_description = 'Fine dining i gammalt mejeri', description = 'Restaurang Kalcium ligger i ett gammalt mejeri från 1902 mitt i Sankt Olof, nära Kivik. Köket lagar skånsk mat med fransk grund och följer säsongen med råvaror från Skåne och Österlen. Restaurangen serverar bara fasta menyer, inte à la carte. Man kan välja fyra serveringar i matsalen, en längre avsmakningsmeny vid Chef''s Table eller en långlunch som är värd en egen utflykt. Kalcium har uppmärksammats av bland andra Dagens Industri och Star Wine List och har fått ett byggnadsvårdspris. Bord bokas på hemsidan.' where id = 67; -- Resturang Kalcium
update public.places set short_description = 'Boende, café och butiker vid Kivik', description = 'Svabesholms Kungsgård ligger nära Kivik och Stenshuvud och samlar mycket på en och samma gård. Här finns gårdshotell och pensionat, ett café och lantkök med frukost och lunch, och flera gårdsbutiker. På gården ligger även Kivik Art Centre och en besöksträdgård, och härifrån går vandringsleder ut i naturen. Gården tar emot grupper och bussresor, bröllop och konferenser, och ordnar evenemang samt jul- och nyårsfirande. Hundar är välkomna, och det finns laddning för elbil. Rum kan bokas direkt på deras hemsida.' where id = 69; -- Svabesholms Kungsgård
update public.places set short_description = 'Skånes äldsta kaffestuga i Alunbruket', description = 'Kaffestugan Alunbruket beskriver sig som Skånes äldsta kaffestuga. Den ligger i en korsvirkeslänga från början av 1700-talet, byggd som arbetarbostad, omgiven av Verkeåns naturreservat. På midsommardagen 1930 började Hilda Nilsson servera kaffe och hembakat i sitt hem, sedan de röda backarna i Alunbruket blivit ett populärt utflyktsmål. I dag drivs kaffestugan av samma familj i fjärde generation. Kaffestugan har funnits med i White Guides urval av Sveriges bästa caféer i många år. Intill ligger Alunbrukets B&B.' where id = 74; -- Kaffestugan Alunbruket
update public.places set short_description = 'Litet bed and breakfast vid Kåseberga', description = 'Vinkille B&B ligger bakom kullarna vid Kåseberga och har tre rymliga och ljusa dubbelrum med utsikt över odlingslandskapet. Alla rum har egen dusch och toalett, i två av rummen ligger badrummet utanför rummet. Det finns tv och trådlöst internet. I priset ingår en riklig frukost i det gemensamma frukostrummet, bäddade sängar och handdukar. När vädret tillåter kan man sitta i trädgården, och gästerna kan låna två cyklar. Hund går bra att ta med om man säger till i förväg, men på gården finns katter och höns.' where id = 75; -- B&B Vinkille
update public.places set short_description = 'Bed and breakfast på skånegård vid havet', description = 'Sjöbacka Gård är en traditionell fyrlängad skånegård från början av 1800-talet, strax utanför Skillinge, med utsikt över hav och äng. Gården har tio individuellt inredda rum och drivs av Ami och Göran sedan 2004. På den vindskyddade innergården kan man ta en kopp kaffe, ett glas vin eller en lunchmacka, och i den stora salen finns ett bibliotek och en brasa. Gården ordnar också vinprovningar och tar emot konferenser, bröllop och fester. Kolla deras hemsida för aktuell information om öppettider innan besöket.' where id = 76; -- Sjöbacka Gård B&B
update public.places set short_description = 'Gård med odlingar, gårdsbutik och självplock', description = 'Angelikas Gård ligger i Norra Björstorp och odlar grönsaker, blommor och plantor. På gården finns också får och höns. Under sommaren kan man handla plantor, grönsaker, ägg, lammskinn och andra produkter i gårdsbutiken och plantshopen, och plocka sina egna snittblommor. Gården säljer även via REKO-ringar runt om i Skåne. Här finns Kafé Solros, som öppnar efter midsommar, och under sommaren och hösten hålls sommar- och skördemarknader. Gården beskriver sig som ett levande kretslopp där mat, blommor och gemenskap växer.' where id = 77; -- Angelikas Gård
update public.places set short_description = 'Hotell vid havet i Simrishamn', description = 'Hotel Svea ligger vid kusten i Simrishamn, nära tågstationen och med utsikt över havet. Hotellet har anor från 1840-talet, då det började som en enkel servering för öl och tilltugg. I dag har hotellet rum med havsutsikt, frukost alla dagar och en restaurang med klassiker och säsongens råvaror, till exempel Skagen och gratinerad bergtunga. Hotellet tar emot konferenser. Från hotellet når man Simrishamns kvarter med gallerier, butiker och kullerstensgator, och flera golfbanor ligger bara några minuter bort.' where id = 78; -- Hotel Svea
update public.places set short_description = 'Dahliaodling med blomsterupplevelse och webbutik', description = 'Dahliafarmen ligger nära Löderup och drivs av Ulrika och Tim. Idén föddes 2019, när de bodde i en villa i Malmö och hade byggt upp en trädgård med ett sjuttiotal dahlior. I dag odlar de dahlior i stor skala på Österlen, med en vid utsikt över landskapet. Under säsongen kan man besöka odlingen och uppleva blommorna på plats. I webbutiken säljs dahliafrön som är odlade och skördade för hand, och man kan förköpa dahliaknölar till nästa säsong.' where id = 80; -- Dahliafarmen
update public.places set short_description = 'Rökeri, fiskbutik och servering i Kåseberga', description = 'Kåseberga Fisk ligger vid havet i Kåseberga och har ett eget rökeri. Här kan man köpa färsk fisk, skaldjur och rökta produkter, och sortimentet går även att beställa online. Vid havet finns en servering, och under sommaren har grillen och restaurangen öppet varje dag. Kåseberga Fisk erbjuder också catering och har en fiskbil. Öppettiderna varierar över året och är längst under sommaren, så det är bra att kolla deras hemsida inför besöket. Röda dagar gäller söndagens öppettider.' where id = 81; -- Kåseberga Fisk
update public.places set short_description = 'Fiskbutik och fiskrestaurang i Simrishamn', description = 'Sjöfolket – Ekströms Fisk & Restaurang är en fiskbutik och fiskrestaurang i Simrishamn. I butiken finns alltid nyrökt fisk och delikatesser som såser, och varje vecka lyfts en särskild fisk fram till ett bra pris. Restaurangen serverar lunch med klassiska fiskrätter. Sjöfolket vill hålla fast vid traditionellt fiske och de gamla sätten att förädla fisk, som rökning, saltning och syrning, och få färsk fisk från båt till tallrik. Fisket har alltid varit en stor del av livet på Österlens fiskelägen.' where id = 82; -- Sjöfolket – Ekströms Fisk & Restaurang
update public.places set short_description = 'Hotell och restaurang vid Stenshuvud', description = 'Allé på Österlen är ett hotell med restaurang söder om Kivik, nära Stenshuvuds nationalpark. Hotellet ligger på en ombyggd gård från 1800-talet där gammalt och nytt möts, och man kör in till gården genom en allé omgiven av äppelodlingar och öppna fält. Platsen beskrivs som ett gömställe för återhämtning, med vida vyer över landskapet. Hotellet har rum och olika paket, och restaurangen serverar middag till hotellgäster och andra. Bokning görs via deras hemsida.' where id = 84; -- Allé på Österlen
update public.places set short_description = 'Hemma-hos-restaurang med 24 platser i Hannas', description = 'Härden Matstudio är en hemma-hos-restaurang i byn Hannas, som drivs av Torkel och Linda i det hus där de också bor. Restaurangen har bara 24 platser och ett öppet kök, så gästerna kan följa arbetet under hela kvällen. Här serveras en fast meny med dryckespaket, och menyn följer säsong och utbud med lokala och ekologiska råvaror så långt det går. Torkel har arbetat som kock i över 20 år, bland annat i Stockholm och Spanien. Restaurangen tar bara emot förbokade gäster.' where id = 85; -- Härden Matstudio
update public.places set short_description = 'Fisk och skaldjur vid kajen i Skillinge', description = 'Skillinge Hamnkrog ligger precis vid kajkanten i Skillinge hamn och drivs av Två Traktörer. Här serveras fisk och skaldjur, med både lunch och middag, och mellan serveringarna dryck, toast Skagen och helstekt rödspätta. Krogen har öppet från mars eller april, beroende på när påsken infaller, till december. Under resten av året kan man boka catering eller hyra krogen för egna sällskap. För Två Traktörer handlar mat om att uppleva smaker, både enkla och välbekanta och lite mer överraskande.' where id = 86; -- Skillinge Hamnkrog
update public.places set short_description = 'Mathall med chark, café och närproducerat', description = 'Smakbruket i Tomelilla är en mötesplats för matintresserade, med fokus på var maten kommer ifrån. Här finns en charkdisk där man kan smaka lammkorv, lokalpressad must och ett utbud av närproducerade, ekologiska varor att handla med sig hem. I caféet kan man äta lunch, läsa en bok eller träffa en vän. Personalen ger gärna tips inför middagen, och Smakbruket ordnar också evenemang. Visionen är att samla det lokala och närproducerade på ett ställe, som ett skyltfönster för bönderna i trakten.' where id = 87; -- Smakbruket
update public.places set short_description = 'Bryggeri och taproom med folklig mat', description = 'Stjärnbryggeriet Taproom i Rörum är ett eget bryggeri med restaurang, dit alla är välkomna. I matsalen serveras vad de kallar folklig fine dining, med lokal öl från det egna bryggeriet och noga utvalda viner. Här finns inga vita dukar, utan klaffbord och en kreativ personal. Restaurangen serverar dagens lunch på vardagarna, med hembakat bröd och kaffe, och middag på fredag- och lördagkvällar. Under året ordnas också livemusik och särskilda middagar, till exempel gåsamiddag på hösten.' where id = 88; -- Stjärnbryggeriet
update public.places set short_description = 'Restaurang på vingården i Simrishamn', description = 'Marcu på Vineriet är en restaurang i Simrishamn med fransk inspiration, i vingården som tidigare hette Nordic Sea Winery. Vingården grundades 2008 och beskrivs som en av norra Europas modernaste vinanläggningar. Restaurangen lagar mat på lokala råvaror som följer säsongen och vill erbjuda en varm och välkomnande miljö. Till maten serveras viner från vingården. Bord kan bokas direkt på hemsidan, där även menyn finns. Restaurangen passar för en middag med vin i fokus.' where id = 89; -- Marcu på Vineriet
update public.places set short_description = 'Gårdshotell strax ovanför Brantevik', description = 'Sköllengården är ett personligt gårdshotell strax ovanför Brantevik, med utsikt över Österlens öppna landskap. Gården är en klassisk skånelänga från slutet av 1600-talet, tidigare en rusthållargård. Den drivs av Kristin och Gustaf med barnen Elicia och Klara, och med katter och en hund på gården. Hållbarhet och lokal förankring står i centrum. Här finns restaurang, paket och konferens, och man kan hyra hela gården. Brantevik och Vyn ligger några minuter bort, och Simrishamn och Skillinge finns nära.' where id = 90; -- Sköllengården
update public.places set short_description = 'Handgjord pasta på svenska spannmål', description = 'Pastafabriken i Ingelstorp gör handgjord pasta på svenska kulturspannmål, i vad de själva kallar norra Europas kanske trevligaste och minsta fabrikslokal. Bakom står samma gäng som driver ett bageri i Ystad och ett pizzaställe i Malmö Saluhall. Den torkade pastan säljs i deras egen och andras butiker, och den färska säljs i en liten deli. På sommaren har restaurangen öppet vissa veckor, och då bokar man inte bord. Här finns även en trädgård och en villa.' where id = 92; -- Pastafabriken i Ingelstorp
update public.places set short_description = 'Hotell och restaurang vid Löderups strand', description = 'Löderups Strandbad är ett hotell med restaurang nära stranden i Löderup. Hit kommer man för att vila, ladda om eller fira livets stora dagar tillsammans med vänner och familj. Personalen tar hand om gästerna och sällskapen, och hotellet beskriver det som det de kan bäst. Under sommaren har hotellet en pool som är öppen för gästerna, och restaurangen serverar bland annat grillbuffé. Rum och paket bokas via hemsidan, där man också hittar aktuella öppettider för restaurangen.' where id = 93; -- Löderups Strandbad
update public.places set short_description = 'Café, restaurang och hotell i Hagestad', description = 'Blå Elefanten ligger mitt i Hagestads radby bland böljande åkrar, ett stenkast från Sandhammaren och Ales stenar. Här finns ett café, en restaurang och ett hotell, som drivs av Jeppe och Pia. De vill att det ska vara opretentiöst, gemytligt och behagligt, och att varje gäst ska känna sig välkommen precis som den är. Caféet serverar lunch och fikabuffé, och restaurangen har öppet vissa kvällar i veckan. Inför jul serveras julbord, ibland med underhållning. Bord och rum bokas via hemsidan.' where id = 94; -- Blå Elefanten
update public.places set short_description = 'Gårdshotell med kafé och hantverksbageri', description = 'Örum 119 är ett personligt gårdshotell nära Löderup, med kafé, hantverksbageri och lokaler för konferens och möten. På gården finns gårdshotellet och Norrgavelhuset, och gästerna kan äta både frukost och middag. I kaféet serveras fika och bröd från det egna hantverksbageriet, och här säljs även glass under namnet Frusen Glädje. Det finns också en butik. Gården beskriver sig som en privat mötesplats för möten och viktiga beslut, men också som ett hem på Österlen. Rum och helgpaket bokas på hemsidan.' where id = 95; -- Örum 119
update public.places set short_description = 'Mat, musik och scen i gammalt stall', description = 'Hannas House är en mötesplats med mat, musik och scen i ett vackert gammalt stall på Österlen, nära Hammenhög. Platsen drivs av Anna-Mia och Sven. Här serveras mat i samband med konserter och andra kvällar, och under året ordnas särskilda middagar som gåsamiddag. Gästerna lyfter fram den goda maten, musiken och den familjära stämningen, ofta med jazz och blues på scenen. Programmet varierar under året, så det är bäst att kolla hemsidan för kommande konserter och middagar innan man bokar.' where id = 96; -- Hannas House
update public.places set short_description = 'Restaurang och hotell vid havet i Brantevik', description = 'Bobergs på Hamngården är en restaurang med åtta ombonade hotellrum i Brantevik, vid havet. Kökschefen Emil Andersson och hans team utvecklar ständigt menyn, där gästerna kan välja en längre avsmakningsmeny eller en mindre meny med fyra rätter. Till maten finns dryckespaket med vin eller alkoholfria alternativ. Hotellgästerna äter frukostbuffé med utsikt över Östersjön. Restaurangen har uppmärksammats av bland andra White Guide och Falstaff. Bobergs drivs av familjen Boberg och Grenz och har öppet från februari till december.' where id = 98; -- Bobergs på Hamngården
update public.places set short_description = 'Restaurang med havsutsikt på Hotel Svea', description = 'Restaurang Piraten ligger på Hotel Svea i Simrishamn, med utsikt över havet. Restaurangen har plats för 130 gäster och passar bra för bröllop och fester. Trädgårdspaviljongen har en egen bar och kan hyras av privata sällskap på upp till 30 personer. Menyn har klassiker och säsongens råvaror, som sillinläggningar, Skagen och gratinerad rödspätta, och det finns ofta ett kvällserbjudande med tre rätter. Restaurangen har öppet varje kväll, och frukost serveras till hotellets gäster varje morgon.' where id = 99; -- Restaurang Piraten på Hotel Svea
update public.places set short_description = 'Familjedriven krog i Simrishamn', description = 'Restaurang Vibe är en familjedriven krog i Simrishamn som drivs av Nour och Lina. Nour står för maten i köket och Lina för stämningen runt omkring. De träffades på Storgatan i Simrishamn, där Nour arbetade efter att ha kommit till Sverige från Syrien, och drömmen om en egen restaurang växte under deras år tillsammans. Restaurangen har plats för omkring 100 gäster inne och lika många ute, och tar emot både stora sällskap och mindre häng. Bord bokas per mejl eller telefon.' where id = 100; -- Restaurang Vibe
update public.places set short_description = 'Svensk och indisk mat i Kivik', description = 'Gröna Äpplet ligger i utkanten av Kivik och serverar en blandning av svensk och indisk mat. Restaurangen har ett gammalt namn men startade om med nya ägare 2019. Kocken har flera års erfarenhet av både svensk och indisk matlagning, och gästerna är välkomna att önska vad de vill äta. Restaurangen serverar lunch och middag från måndag till lördag, och under högsommaren har den öppet varje dag. Det finns också en avhämtningsmeny, och catering erbjuds året runt.' where id = 101; -- Gröna Äpplet
update public.places set short_description = 'Mat, öl, konst och musik i Gladsax', description = 'Lönebostället i Gladsax är en samlingsplats för mat, öl, konst och musik. Här finns ett café med mat, och man brygger egen öl, både vanliga sorter och experimentöl. I galleriet visas konst av Charlotte Adde, och varje år ordnas en kammarmusikfestival i Gladsax. Det finns också en butik och catering. Lönebostället har säsongsöppet och håller bland annat öppet under konstrundan, så det är bäst att kolla hemsidan eller Facebook innan man åker dit. Lönebostället ligger på Gladsax bygata.' where id = 104; -- Lönebostället i Gladsax
update public.places set short_description = 'Kalkonspecialist med gårdsbutik och restaurang', description = 'Ingelsta Kalkon är en svensk, familjeägd kalkonspecialist med gårdsbutik och restaurang mitt på Österlen, i Ingelstorp. I gårdsbutiken finns ett brett sortiment av färska råvaror och delikatesser från gården och andra producenter. Restaurangen serverar mat i en varm miljö. Ingelsta Kalkon delar också med sig av många recept på sin hemsida, från helstekt kalkon på klassiskt vis till marinerat kalkonbröst och thanksgivingkalkon. Här hittar man allt som behövs för en middag att samlas kring, både till vardag och fest.' where id = 105; -- Ingelsta Kalkon
update public.places set short_description = 'Restaurang med lunch och fest i Tomelilla', description = 'Restaurang Mål 19 i Tomelilla serverar veckans lunch måndag till fredag, och menyn finns på hemsidan. Restaurangen vill att varje besök ska vara ett trevligt avbrott i vardagen, i en vacker miljö. Här kan man också boka lokalen för fester och andra tillställningar. Mål 19 erbjuder catering till alla typer av evenemang, från bröllop och företagsmiddagar till födelsedagar och enklare sammankomster, och hjälper gärna till med planeringen. Under julen erbjuds särskilda menyer. Bord och catering bokas på telefon.' where id = 106; -- Mål 19
update public.places set short_description = 'Dansk restaurang med smørrebrød i Tomelilla', description = 'Tinas Lille Danmark är en dansk restaurang mitt i Tomelilla. Här görs smørrebrød först när man beställt, flæskesteg serveras med knastrig svål och kransekage bakas med mandlar som skållas för hand. Tina står själv vid spisen. Restaurangen serverar dagens lunch tisdag till fredag och erbjuder även take away och catering. Inför jul finns bland annat julehyggetallrik och jullandgång. Restaurangen har fullständiga rättigheter, och hundar är välkomna in. Bord bokas via hemsidan, där även hela menyn finns.' where id = 107; -- Tinas Lille Danmark
update public.places set short_description = 'Bed and breakfast, restaurang och butik', description = 'Tryde 1303 är ett hemtrevligt bed and breakfast nära Tomelilla, med sköna sängar och frukost med nybakat bröd och lokala råvaror. Här finns även en restaurang, och lokalerna kan bokas för konferens och kickoff. I butiken säljs produkter från små familjeföretag i Ecuador, som ägarna själva besökt. Konstnären Juan Villavicencios konst finns här och var i huset. Tryde 1303 drivs av Anna, före detta lärare, och Juan, konstnär från Anderna, som arbetar aktivt med hållbarhet.' where id = 108; -- Tryde 1303
update public.places set short_description = 'Rum och restaurang utanför Sankt Olof', description = 'Vita Stenen är ett litet ställe med rum och restaurang, ungefär två kilometer utanför Sankt Olof. Här finns fem rum, med dusch på varje rum och två delade toaletter i korridoren. Restaurangen har fullständiga rättigheter, och maten lagas från grunden på lokalproducerade råvaror. Det finns paket med rum, frukost, trerättersmiddag och välkomstdrink, och Vita Stenen tar även emot konferenser. Härifrån är det nära till Simrishamn, Kivik och Tomelilla. Under sommaren bokas rummen via Booking.com.' where id = 110; -- Vita Stenen
update public.places set short_description = 'Pulled pork och terrass i Brösarps backar', description = 'Grisen & Draken ligger mitt i Brösarps backar och har en terrass med utsikt över backarna. Menyn bygger på pulled pork i flera olika stilar, och det finns en barnmeny. Miljön är inredd i 70-talsstil och passar både familjer och kompisgäng, med långbord och plats för många. Man beställer i baren med sitt bordsnummer, och personalen hjälper gärna till vid allergier eller vegetariska önskemål. Restaurangen har öppet onsdag till söndag, och bord kan bokas online eller per telefon.' where id = 117; -- Grisen & Draken Brösarp
update public.places set short_description = 'Litet hotell och restaurang i Gislöv', description = 'Karnelund är ett litet hotell med restaurang i Gislöv, mitt på Österlen. Här görs allt själva, från duken i matsalen till kudden i fönstret. Köket lagar maten från grunden och låter säsongen bestämma menyn, i två eller tre rätter. Efter middagen är det bara några steg genom trädgården till rummen. Under året serveras särskilda middagar, som gåsamiddag och jul, och till nyår finns en meny för avhämtning. Bord och boende bokas på hemsidan, där även aktuella menyer finns.' where id = 119; -- Karnelund Krog & Rum
update public.places set short_description = 'Konsthall med utställningar och evenemang', description = 'Rikstolvan i Simrishamn är en konsthall som visar utställningar flera gånger om året, oftast en på våren och en på sommaren. Här ordnas också evenemang, som samtal, föreläsningar och visningar med inbjudna gäster. Rikstolvan har en bokshop och ett residens för konstnärer, och i samma hus finns en krog. Programmet varierar från år till år, så det är bra att titta på hemsidan för att se vilken utställning som visas just nu och vilka evenemang som är på gång.' where id = 120; -- Rikstolvan
-- Rättelse: Talldungen ligger i Brösarp
update public.places set nearest_town = 'Brösarp' where id = 16;
commit;
